const s = wb.getWorksheet('DATABASE Countries');
const r = s.getRange('F4:F244');
const fs = [];
for (let row = 4; row <= 244; row++) fs.push([`=SUMPRODUCT(--ISNUMBER(SEARCH(E${row},$A$4:$A$36)),$C$4:$C$36)`]);
r.setValues(fs);
r.getStyle().update({ fill: '#FFC7CE', font: { color: '#9C0006' } });
const vals = r.getValues().flat();
const nz = vals.map((v,i)=>[i+4,v]).filter(x=>x[1]!==0);
log('nonzero', nz, 'count', vals.length, 'types', [...new Set(vals.map(v=>typeof v))]);
log('F4', s.getRange('F4').getFormula().toString().split('\n')[1], 'F244', s.getRange('F244').getFormula().toString().split('\n')[1]);
log(s.getRegions('fill'));
log(s.getRange('F4').getCell()); log(s.getRange('F244').getCell());
log(wb.getRange("'DATABASE Countries'!F2"), wb.getRange("'DATABASE Countries'!C4:C5"), wb.getRange("'DATABASE Countries'!I4:J7"));
log(await wb.evaluate("=SUMIF($A$4:$A$36,E104,$C$4:$C$36)"), await wb.evaluate("=B4/B2"));

